func (self * ERABsToBeSetupItem) Unpack(stream *Stream) {
    dLForwarding_flag := 0x00000002
    iEExtensions_flag := 0x00000004
    const ext_flag = 0x00000001
    _flags := 0
    _extflags := 0
    _ecount := 0
    _flags = stream.get_flags(3)
    self.ERABID.Unpack(stream)// p8
    self.ERABLevelQoSParameters.Unpack(stream)// p8
    if (dLForwarding_flag & _flags) == dLForwarding_flag { //cond2
        self.DLForwarding = &DLForwarding{}//7{'type': 'DL-Forwarding', 'name': 'dL-Forwarding', 'optional': True}
        self.DLForwarding.Unpack(stream)// p8
    }
    self.ULGTPtunnelEndpoint.Unpack(stream)// p8
    if (iEExtensions_flag & _flags) == iEExtensions_flag { //cond2
        self.IEExtensions = &ERABsToBeSetupItemExtIEs{}//7{'type': 'ProtocolExtensionContainer', 'actual-parameters': ['E-RABs-ToBeSetup-ItemExtIEs'], 'name': 'iE-Extensions', 'optional': True}
        IEExtensions := ProtocolExtensionContainer {table_ERABsToBeSetupItemExtIEs, order_ERABsToBeSetupItemExtIEs} // p3
        IEExtensions.Unpack(stream, &self.IEExtensions) // p3
    }
    stream.handle_unknown_ext(_ecount, _extflags, 0, _flags)
    return
}

func (self * ERABsToBeSetupItem) Pack(stream *Stream) {
    const dLForwarding_flag uint = 0x00000002
    const iEExtensions_flag uint = 0x00000004
    const ext_flag int = 0x00000001
    _flagReserve := stream.reserve_flags(3)
    var _extReserve uint32 = 0
    var _extPresent bool = false
    var _flags uint = 0
    var _extflags uint = 0
    self.ERABID.Pack(stream)
    self.ERABLevelQoSParameters.Pack(stream)
    if self.DLForwarding != nil { 
        _flags |= dLForwarding_flag
        self.DLForwarding.Pack(stream)
    }//end of optional
    self.ULGTPtunnelEndpoint.Pack(stream)
    if self.IEExtensions != nil { 
        _flags |= iEExtensions_flag
        IEExtensions := &ProtocolExtensionContainer {table_ERABsToBeSetupItemExtIEs, order_ERABsToBeSetupItemExtIEs} // p3
        IEExtensions.Pack(stream, &self.IEExtensions)
    }//end of optional
    if _extPresent { stream.set_flags(_extflags, _extReserve, 0) }
    stream.set_flags(_flags, _flagReserve, 3)
}//end

