func (self *LastVisitedCellItem)Unpack(stream *Stream) {
    //coptions := []string{"e-UTRAN-Cell","uTRAN-Cell","gERAN-Cell","Unknown","nG-RAN-Cell"}
    choice := stream.get_choice(2, 1, 3)
    choice_len := 0
    choice_loc := 0
    if choice >= 3 {
        choice_len = stream.parse_len(0)
        choice_loc = stream.get_location()
        log.Info("Extension choice option [%d] len %d in LastVisitedCellItem\n", choice, choice_len)
    }
    if choice == 0 { //ch1
        self.EUTRANCell = &LastVisitedEUTRANCellInformation{}//cho6
        self.EUTRANCell.Unpack(stream)
    } else if choice == 1 { //ch2
        self.UTRANCell = &LastVisitedUTRANCellInformation{}//cho6
        self.UTRANCell.Unpack(stream)
    } else if choice == 2 { //ch2
        self.GERANCell = &LastVisitedGERANCellInformation{}//cho6
        self.GERANCell.Unpack(stream)
    } else if choice == 4 { //ch2
        self.NGRANCell = &LastVisitedNGRANCellInformation{}//cho6
        self.NGRANCell.Unpack(stream)
    }//end of if else

    if choice >= 3 {
        stream.set_location(choice_loc, choice_len)
    }
}
func (self * LastVisitedCellItem) Pack(stream *Stream) {
    if self.EUTRANCell != nil {
        stream.set_choice(0, 2, 1, 3)
        self.EUTRANCell.Pack(stream)//2
    } else if self.UTRANCell != nil {
        stream.set_choice(1, 2, 1, 3)
        self.UTRANCell.Pack(stream)//2
    } else if self.GERANCell != nil {
        stream.set_choice(2, 2, 1, 3)
        self.GERANCell.Pack(stream)//2
    } else if self.NGRANCell != nil {
        stream.set_choice(4, 2, 1, 3)
        lenLoc := stream.reserve_len()
        self.NGRANCell.Pack(stream)//2
        stream.set_len(lenLoc)
    }

}
