func (self *MeasurementThresholdA2)Unpack(stream *Stream) {
    //coptions := []string{"threshold-RSRP","threshold-RSRQ"}
    choice := stream.get_choice(1, 1, 2)
    choice_len := 0
    choice_loc := 0
    if choice >= 2 {
        choice_len = stream.parse_len(0)
        choice_loc = stream.get_location()
        log.Info("Extension choice option [%d] len %d in MeasurementThresholdA2\n", choice, choice_len)
    }
    if choice == 0 { //ch1
        self.ThresholdRSRP = &ThresholdRSRP{}//cho6
        self.ThresholdRSRP.Unpack(stream)
    } else if choice == 1 { //ch2
        self.ThresholdRSRQ = &ThresholdRSRQ{}//cho6
        self.ThresholdRSRQ.Unpack(stream)
    }//end of if else

    if choice >= 2 {
        stream.set_location(choice_loc, choice_len)
    }
}
func (self * MeasurementThresholdA2) Pack(stream *Stream) {
    if self.ThresholdRSRP != nil {
        stream.set_choice(0, 1, 1, 2)
        self.ThresholdRSRP.Pack(stream)//2
    } else if self.ThresholdRSRQ != nil {
        stream.set_choice(1, 1, 1, 2)
        self.ThresholdRSRQ.Pack(stream)//2
    }

}
