func (self *SharedResourceType)Unpack(stream *Stream) {
    //coptions := []string{"uLOnlySharing","uLandDLSharing"}
    choice := stream.get_choice(1, 1, 2)
    choice_len := 0
    choice_loc := 0
    if choice >= 2 {
        choice_len = stream.parse_len(0)
        choice_loc = stream.get_location()
        log.Info("Extension choice option [%d] len %d in SharedResourceType\n", choice, choice_len)
    }
    if choice == 0 { //ch1
        self.ULOnlySharing = &ULOnlySharing{}//cho6
        self.ULOnlySharing.Unpack(stream)
    } else if choice == 1 { //ch2
        self.ULandDLSharing = &ULandDLSharing{}//cho6
        self.ULandDLSharing.Unpack(stream)
    }//end of if else

    if choice >= 2 {
        stream.set_location(choice_loc, choice_len)
    }
}
func (self * SharedResourceType) Pack(stream *Stream) {
    if self.ULOnlySharing != nil {
        stream.set_choice(0, 1, 1, 2)
        self.ULOnlySharing.Pack(stream)//2
    } else if self.ULandDLSharing != nil {
        stream.set_choice(1, 1, 1, 2)
        self.ULandDLSharing.Pack(stream)//2
    }

}
